package builder
import("encoding/json";"fmt";"sort";"strings")
type Manifest struct{Name string `json:"name"`;Template string `json:"template"`;Backend string `json:"backend,omitempty"`;Database string `json:"database,omitempty"`;Environment map[string]string `json:"environment,omitempty"`;Features []string `json:"features,omitempty"`}
func(m Manifest)Validate()error{if strings.TrimSpace(m.Name)==""{return fmt.Errorf("name is required")};if strings.TrimSpace(m.Name)!=""&&len(strings.TrimSpace(m.Name))>256{return fmt.Errorf("name is too large")};if strings.TrimSpace(m.Template)==""||len(strings.TrimSpace(m.Template))>128{return fmt.Errorf("template is required or too large")};if _,err:=GetTemplate(strings.TrimSpace(m.Template));err!=nil{return err};if len(m.Environment)>256||len(m.Features)>256{return fmt.Errorf("manifest contains too many entries")};for k,v:=range m.Environment{key:=strings.TrimSpace(k);if key==""||len(key)>128{return fmt.Errorf("environment key is invalid")};if len(v)>4096||strings.ContainsAny(key,"=\r\n")||strings.ContainsAny(v,"\r\n"){return fmt.Errorf("environment contains invalid key or value")}};return nil}
func(m Manifest)Normalize()Manifest{m.Name=strings.TrimSpace(m.Name);m.Template=strings.TrimSpace(m.Template);m.Backend=strings.TrimSpace(m.Backend);m.Database=strings.TrimSpace(m.Database);if m.Environment!=nil{env:=make(map[string]string,len(m.Environment));for k,v:=range m.Environment{k=strings.TrimSpace(k);if k==""||len(k)>128{continue};if len(v)>4096{v=v[:4096]};env[k]=strings.TrimSpace(v)};m.Environment=env};seen:=map[string]struct{}{};features:=make([]string,0,len(m.Features));for _,f:=range m.Features{f=strings.TrimSpace(f);if f==""{continue};if _,ok:=seen[f];ok{continue};seen[f]=struct{}{};features=append(features,f);if len(features)>=256{break}};sort.Strings(features);m.Features=features;return m}
func EncodeManifest(m Manifest)([]byte,error){m=m.Normalize();if err:=m.Validate();err!=nil{return nil,err};return json.MarshalIndent(m,"","  ")}
